局部操作互斥、读和送需同步，
Semaphore mutex=1 ; //互斥用信箱
semaphore empty=10; //空信箱数
semaphore full=0 ; //已站用数
item mbox[N]; //信箱
int in=0, out=0; //信箱队列的首尾，
master() { //主人进程
while(1) {
P(full);
P(mutex);
read= mbox[out];
out=(out+1)%N; //读信
V(mutex);
V(empty);
}
}
others() { //其他用户
P(empty); 写信;
P(mutex);
mbox[in]=put;
put=(1+put)%N /送信
V(mutex);
V(full);
}

